    /**
     * Whether this loader carries the loot of the stones that mod places. The generator writes a placed
     * stone's tables only to the loaders the mod ships for, so on any other one (a build that appeared
     * later, a port on one platform only) its variants would drop nothing: there the stone gets none, and
     * the ore in it keeps its own look.
     */
    static boolean shipsHere(String mod) {
        final String here = Services.PLATFORM.getPlatformName().toLowerCase(Locale.ROOT);
        return switch (mod) {
            // BEGIN GENERATED stone loaders (tools/generate_assets.py, from its loot routing)
            case "minecraft" -> here.equals("fabric") || here.equals("neoforge");
            case "blockus" -> here.equals("fabric");
            case "create" -> here.equals("fabric");
            case "forbidden_arcanus" -> here.equals("neoforge");
            case "mythicupgrades" -> here.equals("fabric") || here.equals("neoforge");
            case "regions_unexplored" -> here.equals("fabric") || here.equals("neoforge");
            case "promenade" -> here.equals("fabric") || here.equals("neoforge");
            case "wilderwild" -> here.equals("fabric") || here.equals("neoforge");
            case "yungscavebiomes" -> here.equals("fabric") || here.equals("neoforge");
            case "natures_spirit" -> here.equals("fabric") || here.equals("neoforge");
            // END GENERATED stone loaders
            default -> false;
        };
    }

    private static List<OreType> keys(String... keys) {
        final List<OreType> ores = new ArrayList<>(keys.length);
        for (String key : keys) {
            final OreType ore = OreType.byKey(key);
            if (ore == null) {
                Constants.LOG.error("The modded pairs name an ore key {} the ore table does not have", key);
            } else {
                ores.add(ore);
            }
        }
        return ores;
    }
